import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        department TEXT,
        salary REAL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        query TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department with optional field selection.
    Requires valid session token checked upstream.
    """
    department = request.args.get('department', '')
    fields = request.args.get('fields', 'username,email,department')
    page = request.args.get('page', '1')

    # Validate page is numeric
    if not page.isdigit():
        return jsonify({'error': 'Invalid page parameter'}), 400

    # Basic field validation - only allow alphanumeric and underscore
    for field in fields.split(','):
        if not field.strip().replace('_', '').isalnum():
            return jsonify({'error': f'Invalid field name: {field}'}), 400

    offset = (int(page) - 1) * 20

    # Build query with validated fields
    query = f"SELECT {fields} FROM users WHERE department = '{department}' LIMIT 20 OFFSET {offset}"

    # Log the query for compliance
    try:
        db = get_db()
        db.execute("INSERT INTO audit_log (action, query) VALUES (?, ?)",
                   ('search', query))
        db.commit()
    except Exception:
        pass  # Don't fail on audit log errors

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'page': int(page)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID. Access control handled by upstream proxy."""
    db = get_db()
    cursor = db.execute("SELECT username, email, department FROM users WHERE id = ?", (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
